// Whale Road: painted sea chart art (map owner).
// Everything is drawn in code: parchment, watercolour seas, coast ripples, brush-stroke
// mountains and forests, lakes and rivers, region names, a compass rose, sea creatures,
// longships, a cartouche and a graduated border. All coordinates are map units of the
// 1000 x 772 chart in js/data/coast.js; the chart SVG adds a MARGIN-wide frame around it.

import {COAST, MAP_W, MAP_H} from '../data/coast.js';
import {project, LANES} from '../data/routes.js';

/** Map units a fleet covers on a day of fair sailing (scale bar, fallback travel estimate). */
export const UNITS_PER_DAY = 45;

export const MARGIN = 26;
export const VIEW = {x: -MARGIN, y: -MARGIN, w: MAP_W + 2 * MARGIN, h: MAP_H + 2 * MARGIN};

const INK = '#1d1a16', PARCH = '#efe2c4', PARCH_DK = '#d9c59a', WOOD = '#5b3a22', WOOD_DK = '#3a2414';
const GOLD = '#c99a2e', SEA = '#2f5d6e', SEA_DK = '#183a48', BLOOD = '#8e2a22', MOSS = '#5f6b3a', SNOW = '#f4f1ea';
export const FONT_TITLE = "Cinzel, 'Trajan Pro', 'Times New Roman', serif";
export const FONT_BODY = "Alegreya, 'Iowan Old Style', Georgia, serif";

const f = (n) => Math.round(n * 10) / 10;
const P = (lon, lat) => project(lon, lat);
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Catmull-Rom spline through points -> SVG path data. */
export function smooth(pts, closed = false) {
  const n = pts.length;
  if (n < 3) return 'M' + pts.map((p) => f(p[0]) + ',' + f(p[1])).join('L');
  const get = (i) => closed ? pts[(i + n) % n] : pts[Math.max(0, Math.min(n - 1, i))];
  let d = `M${f(pts[0][0])},${f(pts[0][1])}`;
  const last = closed ? n : n - 1;
  for (let i = 0; i < last; i++) {
    const p0 = get(i - 1), p1 = get(i), p2 = get(i + 1), p3 = get(i + 2);
    d += `C${f(p1[0] + (p2[0] - p0[0]) / 6)},${f(p1[1] + (p2[1] - p0[1]) / 6)} ${f(p2[0] - (p3[0] - p1[0]) / 6)},${f(p2[1] - (p3[1] - p1[1]) / 6)} ${f(p2[0])},${f(p2[1])}`;
  }
  return d + (closed ? 'Z' : '');
}
const llPath = (ll, closed) => smooth(ll.map(([lo, la]) => P(lo, la)), closed);

/** Irregular watercolour blot around (cx, cy). */
function blob(r, cx, cy, rx, ry, k = 0.28, n = 11) {
  const pts = [];
  const ph = r() * 6.28;
  for (let i = 0; i < n; i++) {
    const a = ph + (i / n) * Math.PI * 2;
    const m = 1 - k + r() * k * 2;
    pts.push([cx + Math.cos(a) * rx * m, cy + Math.sin(a) * ry * m]);
  }
  return smooth(pts, true);
}

