// ---------------------------------------------------------------- decorations
function compassRose(cx, cy, R) {
  const pt = (a, r) => `${f(cx + Math.sin(a) * r)},${f(cy - Math.cos(a) * r)}`;
  let s = `<g class="wm-rose">`;
  // rhumb lines radiating across the sea (drawn under land elsewhere)
  s += `<circle cx="${cx}" cy="${cy}" r="${R * 1.08}" fill="${PARCH}" opacity=".55"/>`;
  s += `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="${INK}" stroke-width=".9"/>`;
  s += `<circle cx="${cx}" cy="${cy}" r="${R * 0.9}" fill="none" stroke="${INK}" stroke-width=".5"/>`;
  for (let i = 0; i < 64; i++) {
    const a = (i / 64) * Math.PI * 2, long = i % 8 === 0, mid = i % 4 === 0;
    s += `<path d="M${pt(a, R * 0.9)}L${pt(a, R * (long ? 0.78 : mid ? 0.83 : 0.86))}" stroke="${INK}" stroke-width="${long ? 0.8 : 0.4}"/>`;
  }
  // knot band between the rings: alternating ink and gold arcs
  for (let i = 0; i < 16; i++) {
    const a0 = (i / 16) * Math.PI * 2, a1 = ((i + 1) / 16) * Math.PI * 2, r = R * 0.95;
    s += `<path d="M${pt(a0, r)}A${r},${r} 0 0 1 ${pt(a1, r)}" stroke="${i % 2 ? GOLD : BLOOD}" stroke-width="${R * 0.05}" fill="none" opacity=".75"/>`;
  }
  // sixteen points: small gold, then eight ink points (four long)
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2 + Math.PI / 16;
    s += `<path d="M${pt(a, R * 0.62)}L${pt(a - 0.09, R * 0.2)}L${pt(a + 0.09, R * 0.2)}Z" fill="${GOLD}" stroke="${INK}" stroke-width=".3" opacity=".9"/>`;
  }
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2, L = i % 2 ? R * 0.68 : R * 0.98, w = i % 2 ? 0.2 : 0.17, r0 = R * 0.16;
    s += `<path d="M${pt(a, L)}L${pt(a - w, r0)}L${f(cx)},${f(cy)}Z" fill="${i % 2 ? SEA : INK}"/>`;
    s += `<path d="M${pt(a, L)}L${pt(a + w, r0)}L${f(cx)},${f(cy)}Z" fill="${PARCH}" stroke="${INK}" stroke-width=".45"/>`;
  }
  // sun wheel at the centre
  s += `<circle cx="${cx}" cy="${cy}" r="${R * 0.13}" fill="${GOLD}" stroke="${INK}" stroke-width=".6"/>`;
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2;
    s += `<path d="M${f(cx)},${f(cy)}Q${pt(a + 0.6, R * 0.08)} ${pt(a + 0.25, R * 0.13)}" stroke="${INK}" stroke-width=".55" fill="none"/>`;
  }
  // north marker and the four dwarves who hold up the sky
  s += `<path d="M${pt(0, R * 1.22)}L${pt(-0.07, R * 1.02)}Q${pt(0, R * 1.07)} ${pt(0.07, R * 1.02)}Z" fill="${BLOOD}" stroke="${INK}" stroke-width=".5"/>`;
  const names = [['NORÐRI', 0], ['AUSTRI', Math.PI / 2], ['SUÐRI', Math.PI], ['VESTRI', -Math.PI / 2]];
  for (const [n, a] of names) {
    const r = R * 1.15, x = cx + Math.sin(a) * r, y = cy - Math.cos(a) * r;
    const rot = a === Math.PI ? 0 : (a * 180) / Math.PI;
    s += `<text x="${f(x)}" y="${f(y)}" transform="rotate(${f(rot % 180 === 0 ? 0 : rot)} ${f(x)} ${f(y)})" text-anchor="middle" dominant-baseline="middle" font-family="${FONT_TITLE}" font-size="${f(R * 0.13)}" letter-spacing="1" fill="${WOOD_DK}" font-weight="700">${n}</text>`;
  }
  return s + '</g>';
}

function rhumbs(cx, cy) {
  let d = '';
  for (let i = 0; i < 32; i++) {
    const a = (i / 32) * Math.PI * 2;
    d += `M${cx},${cy}L${f(cx + Math.sin(a) * 1500)},${f(cy - Math.cos(a) * 1500)}`;
  }
  return `<path d="${d}" stroke="${WOOD}" stroke-width=".35" opacity=".16" fill="none"/>`;
}

