function scaleBar(x, y, unitsPerDay) {
  let s = `<g class="wm-scale"><text x="${x}" y="${y - 6}" font-family="${FONT_BODY}" font-style="italic" font-size="9" fill="${WOOD_DK}">Days of fair sailing</text>`;
  const n = 3;
  for (let i = 0; i < n; i++) {
    s += `<rect x="${f(x + i * unitsPerDay)}" y="${y}" width="${f(unitsPerDay)}" height="4" fill="${i % 2 ? PARCH : INK}" stroke="${INK}" stroke-width=".5"/>`;
    s += `<text x="${f(x + i * unitsPerDay)}" y="${y + 13}" text-anchor="middle" font-family="${FONT_BODY}" font-size="8" fill="${WOOD_DK}">${i}</text>`;
  }
  return s + `<text x="${f(x + n * unitsPerDay)}" y="${y + 13}" text-anchor="middle" font-family="${FONT_BODY}" font-size="8" fill="${WOOD_DK}">${n}</text></g>`;
}

function frame() {
  const M = MARGIN;
  let s = `<rect x="${-M}" y="${-M}" width="${MAP_W + 2 * M}" height="${MAP_H + 2 * M}" fill="${PARCH_DK}"/>`;
  s += `<rect x="${-M + 2}" y="${-M + 2}" width="${MAP_W + 2 * M - 4}" height="${MAP_H + 2 * M - 4}" fill="none" stroke="${WOOD_DK}" stroke-width="2.4"/>`;
  s += `<rect x="${-M + 5}" y="${-M + 5}" width="${MAP_W + 2 * M - 10}" height="${MAP_H + 2 * M - 10}" fill="none" stroke="${WOOD_DK}" stroke-width=".6"/>`;
  // graduated band: one cell per degree of longitude and latitude
  const b0 = -14, bw = 8;
  let dark = '';
  for (let lon = -26; lon < 44; lon++) {
    if (lon % 2) continue;
    const x0 = P(lon, 50)[0], x1 = P(lon + 1, 50)[0];
    dark += `M${f(x0)},${b0}h${f(x1 - x0)}v${bw}h${f(x0 - x1)}Z M${f(x0)},${MAP_H + 6}h${f(x1 - x0)}v${bw}h${f(x0 - x1)}Z`;
  }
  for (let lat = 38; lat < 68.5; lat++) {
    if (lat % 2) continue;
    const y0 = P(0, Math.min(68.5, lat + 1))[1], y1 = P(0, lat)[1];
    dark += `M${b0},${f(y0)}v${f(y1 - y0)}h${bw}v${f(y0 - y1)}Z M${MAP_W + 6},${f(y0)}v${f(y1 - y0)}h${bw}v${f(y0 - y1)}Z`;
  }
  s += `<rect x="${b0}" y="${b0}" width="${MAP_W - 2 * b0}" height="${MAP_H - 2 * b0}" fill="none" stroke="${INK}" stroke-width=".7"/>`;
  s += `<rect x="${b0 + bw}" y="${b0 + bw}" width="${MAP_W - 2 * (b0 + bw)}" height="${MAP_H - 2 * (b0 + bw)}" fill="none" stroke="${INK}" stroke-width=".7"/>`;
  s += `<path d="${dark}" fill="${WOOD}" opacity=".85"/>`;
  // corner knots
  for (const [cx, cy] of [[-M + 13, -M + 13], [MAP_W + M - 13, -M + 13], [-M + 13, MAP_H + M - 13], [MAP_W + M - 13, MAP_H + M - 13]]) {
    s += `<rect x="${cx - 9}" y="${cy - 9}" width="18" height="18" fill="${PARCH}" stroke="${INK}" stroke-width=".8"/>`;
    s += `<path d="M${cx - 6},${cy} C${cx - 6},${cy - 8} ${cx + 6},${cy + 8} ${cx + 6},${cy} C${cx + 6},${cy - 8} ${cx - 6},${cy + 8} ${cx - 6},${cy}Z M${cx},${cy - 6} C${cx + 8},${cy - 6} ${cx - 8},${cy + 6} ${cx},${cy + 6} C${cx + 8},${cy + 6} ${cx - 8},${cy - 6} ${cx},${cy - 6}Z" fill="none" stroke="${BLOOD}" stroke-width="1.1"/>`;
  }
  return s;
}

function labelsSVG() {
  let defs = '', txt = '';
  REGION_LABELS.forEach(([t, kind, size, pts], i) => {
    const id = `wm-lp${i}`;
    // stretch the baseline so the whole word fits (textPath clips overflowing glyphs)
    const xy = pts.map(([lo, la]) => P(lo, la));
    let L = 0;
    for (let k = 1; k < xy.length; k++) L += Math.hypot(xy[k][0] - xy[k - 1][0], xy[k][1] - xy[k - 1][1]);
    const ls = kind === 'sea' ? size * 0.22 : kind === 'grand' ? size * 0.5 : size * 0.18;
    const need = t.length * (size * (kind === 'sea' ? 0.5 : 0.78) + ls) * 1.15 + 10;
    if (need > L) {
      const ext = (need - L) / 2, n = xy.length;
      const e0 = xy[0], e1 = xy[1], z0 = xy[n - 1], z1 = xy[n - 2];
      const d0 = Math.hypot(e0[0] - e1[0], e0[1] - e1[1]) || 1, d1 = Math.hypot(z0[0] - z1[0], z0[1] - z1[1]) || 1;
      xy.unshift([e0[0] + ((e0[0] - e1[0]) / d0) * ext, e0[1] + ((e0[1] - e1[1]) / d0) * ext]);
      xy.push([z0[0] + ((z0[0] - z1[0]) / d1) * ext, z0[1] + ((z0[1] - z1[1]) / d1) * ext]);
    }
    defs += `<path id="${id}" d="${smooth(xy, false)}"/>`;
    const style = kind === 'sea'
      ? `font-family="${FONT_BODY}" font-style="italic" fill="${SEA_DK}" opacity=".62" letter-spacing="${f(size * 0.22)}"`
      : kind === 'grand'
        ? `font-family="${FONT_TITLE}" font-weight="700" fill="${BLOOD}" opacity=".5" letter-spacing="${f(size * 0.5)}"`
        : `font-family="${FONT_TITLE}" font-weight="600" fill="${WOOD_DK}" opacity=".8" letter-spacing="${f(size * 0.18)}" stroke="${PARCH}" stroke-width="${f(size * 0.28)}" stroke-opacity=".75" paint-order="stroke" stroke-linejoin="round"`;
    txt += `<text font-size="${size}" ${style} class="wm-label wm-${kind}"><textPath href="#${id}" startOffset="50%" text-anchor="middle">${kind === 'grand' ? t.toUpperCase() : t}</textPath></text>`;
  });
  return {defs, txt};
}

function lanesSVG() {
  let sea = '', river = '', portage = '';
  for (const l of LANES) {
    const d = 'M' + l.points.map((p) => f(p[0]) + ',' + f(p[1])).join('L');
    if (l.kind === 'sea') sea += d; else if (l.kind === 'river') river += d; else portage += d;
  }
  return `<g class="wm-lanes" fill="none" stroke-linecap="round" stroke-linejoin="round">
<path d="${sea}" stroke="${WOOD}" stroke-width="1.15" stroke-dasharray="0.01 3.6" opacity=".55"/>
<path d="${river}" stroke="${WOOD}" stroke-width=".9" stroke-dasharray="2.2 2" opacity=".55"/>
<path d="${portage}" stroke="${BLOOD}" stroke-width="1.1" stroke-dasharray="3 1.6 0.01 1.6" opacity=".7"/></g>`;
}

/**
 * The full static chart as an SVG string (viewBox = VIEW, so map coords are native).
 * opts: {lanes: true}
 */
export function chartSVG(opts = {}) {
  const {lanes = true} = opts;
  const r = rng(950);
  const W = MAP_W, H = MAP_H;
  const lab = labelsSVG();
  const rose = P(-16.5, 47.6), roseR = 46;
  const blot = (cx, cy, rx, ry, fill, op, n = 1) => {
    let s = '';
    for (let i = 0; i < n; i++) s += `<path d="${blob(r, cx + (r() - 0.5) * rx * 0.5, cy + (r() - 0.5) * ry * 0.5, rx, ry)}" fill="${fill}" opacity="${op}"/>`;
    return s;
  };
  const at = (lon, lat) => P(lon, lat);

  // sea washes
  let seaWash = '';
  for (const [lon, lat, rx, ry] of [[-18, 58, 150, 120], [-12, 64.5, 140, 70], [0, 67, 160, 60], [-20, 45, 110, 120], [3, 66, 90, 60], [-8, 48.5, 70, 50]]) {
    const [x, y] = at(lon, lat);
    seaWash += blot(x, y, rx, ry, '#4f7c88', 0.16, 3);
  }
  for (const [lon, lat, rx, ry] of [[3, 55.5, 70, 70], [18, 56, 60, 50], [20, 61.5, 25, 60], [34, 43.3, 70, 30], [8, 40, 60, 25], [25, 59.8, 40, 12]]) {
    const [x, y] = at(lon, lat);
    seaWash += blot(x, y, rx, ry, '#d6dfca', 0.3, 2);
  }
  // land washes
  let landWash = '';
  const greens = [[15, 61.5, 70, 70], [25, 63, 60, 40], [31, 60.5, 60, 40], [37, 58.5, 80, 50], [33, 55.5, 60, 40], [22, 55.5, 50, 30], [11, 51.5, 60, 30], [-3, 53.5, 25, 30], [10, 59.8, 18, 16], [3, 48.5, 50, 30], [-7.5, 53.2, 16, 18]];
  for (const [lon, lat, rx, ry] of greens) { const [x, y] = at(lon, lat); landWash += blot(x, y, rx, ry, '#8d9a5c', 0.2, 3); }
  for (const [lon, lat, rx, ry] of [[34, 47.5, 90, 35], [-4, 40.5, 60, 35], [33, 39.5, 70, 25], [24, 44.5, 60, 25]]) { const [x, y] = at(lon, lat); landWash += blot(x, y, rx, ry, '#cfa45c', 0.22, 3); }
  for (const [lon, lat, rx, ry] of [[-18.5, 64.9, 45, 18], [15, 67, 30, 25], [9, 61.6, 22, 14], [42, 43, 25, 8], [9.5, 46.4, 40, 10]]) { const [x, y] = at(lon, lat); landWash += blot(x, y, rx, ry, SNOW, 0.5, 2); }

  // inland water
  const lakes = Object.values(LAKES).map((ll) => llPath(ll, true)).join('');
  const rivers = Object.values(RIVERS).map((ll) => llPath(ll, false)).join('');

  // glyphs
  const mtn = unpack(GEN.mountains).map(([x, y, sz]) => `<use href="#${sz > 1.15 ? 'wm-mtns' : 'wm-mtn'}" transform="translate(${x},${y}) scale(${sz})"/>`).join('');
  const trees = unpack(GEN.trees).map(([x, y, k]) => `<use href="#${k ? 'wm-oak' : 'wm-fir'}" x="${x}" y="${y}"/>`).join('');
  const tufts = unpack(GEN.tufts).map(([x, y]) => `<use href="#wm-tuft" x="${x}" y="${y}"/>`).join('');
  const waves = unpack(GEN.waves).map(([x, y]) => `<use href="#wm-wave" x="${x}" y="${y}" opacity=".35"/>`).join('');

  const ring = (w, id) => `<mask id="${id}" maskUnits="userSpaceOnUse" x="${-MARGIN}" y="${-MARGIN}" width="${VIEW.w}" height="${VIEW.h}"><rect x="${-MARGIN}" y="${-MARGIN}" width="${VIEW.w}" height="${VIEW.h}" fill="#fff"/><path d="${COAST}" fill="#000" fill-rule="evenodd" stroke="#000" stroke-width="${w - 0.9}"/></mask>`;
  const [cx0, cy0] = at(-25.2, 41.7);
  const sb = at(-24.6, 44.0);

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${VIEW.x} ${VIEW.y} ${VIEW.w} ${VIEW.h}" class="wm-chart" preserveAspectRatio="xMidYMid meet">
<defs>
${SYMBOLS}
<linearGradient id="wm-sea" x1="0" y1="0" x2="0.25" y2="1"><stop offset="0" stop-color="#8eaaa8"/><stop offset=".45" stop-color="#a7bdb2"/><stop offset="1" stop-color="#b9c6ad"/></linearGradient>
<radialGradient id="wm-land" cx=".55" cy=".45" r=".75"><stop offset="0" stop-color="#efe3c3"/><stop offset="1" stop-color="#e3d2a8"/></radialGradient>
<radialGradient id="wm-vig" cx=".5" cy=".5" r=".72"><stop offset=".62" stop-color="${WOOD}" stop-opacity="0"/><stop offset="1" stop-color="${WOOD}" stop-opacity=".32"/></radialGradient>
<clipPath id="wm-clipmap"><rect x="0" y="0" width="${W}" height="${H}"/></clipPath>
<clipPath id="wm-clipland"><path d="${COAST}" clip-rule="evenodd"/></clipPath>
${ring(5, 'wm-r1')}${ring(10.5, 'wm-r2')}${ring(18, 'wm-r3')}
${lab.defs}
</defs>
${frame()}
<g clip-path="url(#wm-clipmap)">
<rect x="0" y="0" width="${W}" height="${H}" fill="url(#wm-sea)"/>
${seaWash}
${rhumbs(rose[0], rose[1])}
${waves}
<g fill="none" stroke-linejoin="round">
<path d="${COAST}" stroke="#2f5d6e" stroke-width="30" opacity=".07"/>
<path d="${COAST}" stroke="#2f5d6e" stroke-width="16" opacity=".09"/>
<path d="${COAST}" stroke="#2f5d6e" stroke-width="7" opacity=".14"/>
<path d="${COAST}" stroke="${SEA_DK}" stroke-width="5" opacity=".42" mask="url(#wm-r1)"/>
<path d="${COAST}" stroke="${SEA_DK}" stroke-width="10.5" opacity=".26" mask="url(#wm-r2)"/>
<path d="${COAST}" stroke="${SEA_DK}" stroke-width="18" opacity=".15" mask="url(#wm-r3)"/>
</g>
<path d="${COAST}" fill="url(#wm-land)" fill-rule="evenodd"/>
<g clip-path="url(#wm-clipland)">
${landWash}
<path d="${COAST}" fill="none" stroke="#b9975f" stroke-width="7" opacity=".38"/>
<path d="${COAST}" fill="none" stroke="#a5824c" stroke-width="2.4" opacity=".4"/>
<path d="${rivers}" fill="none" stroke="#e9f0e6" stroke-width="2.2" stroke-linecap="round" opacity=".6"/>
<path d="${rivers}" fill="none" stroke="#3f6f80" stroke-width=".95" stroke-linecap="round" opacity=".85"/>
<path d="${lakes}" fill="#a3bcb3" stroke="#3f6f80" stroke-width="3" stroke-opacity=".15"/>
<path d="${lakes}" fill="none" stroke="${INK}" stroke-width=".5" opacity=".8"/>
${tufts}
${trees}
${mtn}
</g>
<path d="${COAST}" fill="none" stroke="${INK}" stroke-width="1.8" opacity=".12" stroke-linejoin="round"/>
<path d="${COAST}" fill="none" stroke="${INK}" stroke-width=".62" opacity=".85" stroke-linejoin="round"/>
${lanes ? lanesSVG() : ''}
${lab.txt}
${whale(...at(-16.5, 61.0), 1)}
${serpent(...at(2.0, 66.2), 1.05)}
${kraken(...at(-21.5, 57.2), 1)}
${longship(...at(3.6, 57.4), 0.55, false)}
${longship(...at(18.6, 55.6), 0.45, true, '#2f5d6e')}
${longship(...at(-14, 63.9), 0.5, true)}
${longship(...at(33.4, 44.2), 0.45, false, '#6d2d6b')}
${compassRose(rose[0], rose[1], roseR)}
${cartouche(cx0, cy0, 214, 70)}
${scaleBar(sb[0] + 22, sb[1] + 16, UNITS_PER_DAY)}
<rect x="0" y="0" width="${W}" height="${H}" fill="url(#wm-vig)" pointer-events="none"/>
</g>
<rect x="0" y="0" width="${W}" height="${H}" fill="none" stroke="${INK}" stroke-width="1.2"/>
</svg>`;
}

/** Tileable paper grain as a data URL (browser only; '' elsewhere). */
let paperURL = null;
export function paperTexture() {
  if (paperURL !== null) return paperURL;
  paperURL = '';
  try {
    const c = document.createElement('canvas');
    c.width = c.height = 192;
    const g = c.getContext('2d');
    const img = g.createImageData(192, 192), r = rng(7);
    for (let i = 0; i < img.data.length; i += 4) {
      const v = 200 + r() * 55;
      img.data[i] = v; img.data[i + 1] = v * 0.96; img.data[i + 2] = v * 0.88; img.data[i + 3] = 255;
    }
    g.putImageData(img, 0, 0);
    // a few fibres and blotches
    for (let i = 0; i < 60; i++) {
      g.strokeStyle = `rgba(120,90,50,${0.04 + r() * 0.05})`;
      g.lineWidth = 0.6;
      g.beginPath();
      const x = r() * 192, y = r() * 192, a = r() * 6.28, L = 6 + r() * 18;
      g.moveTo(x, y);
      g.quadraticCurveTo(x + Math.cos(a + 0.5) * L / 2, y + Math.sin(a + 0.5) * L / 2, x + Math.cos(a) * L, y + Math.sin(a) * L);
      g.stroke();
    }
    paperURL = c.toDataURL('image/png');
  } catch (e) { paperURL = ''; }
  return paperURL;
}

