/** Round port medallion, viewBox -18 -18 36 36. */
export function portMedallion(culture, {locked = false, current = false, size = 36} = {}) {
  const ring = locked ? '#8a7a5c' : (CULTURE_COLORS[culture] || INK);
  const inner = locked
    ? `<text y="1" text-anchor="middle" dominant-baseline="middle" font-family="${FONT_TITLE}" font-weight="700" font-size="17" fill="#5b4a32">?</text>`
    : cultureIcon(culture);
  return `<svg viewBox="-18 -18 36 36" width="${size}" height="${size}" aria-hidden="true">
${current ? `<circle r="17" fill="none" stroke="${GOLD}" stroke-width="2.2"/>` : ''}
<circle r="14" fill="${locked ? '#d8c8a2' : '#f5ebd2'}" stroke="${ring}" stroke-width="2.6" ${locked ? 'stroke-dasharray="3 2"' : ''}/>
<circle r="11.4" fill="none" stroke="${INK}" stroke-width=".55" opacity=".45"/>
${inner}</svg>`;
}

