/** Map-side quest badge (gold main / blue side), viewBox -10 -12 20 22. */
export function questBadge(kind, size = 20) {
  const c = kind === 'main' ? GOLD : '#3f78b5';
  return `<svg viewBox="-10 -12 20 22" width="${size}" height="${size * 1.1}" aria-hidden="true"><path d="M-8,-10H8V1C8,6 3,8.6 0,10C-3,8.6 -8,6 -8,1Z" fill="${c}" stroke="${INK}" stroke-width="1.4" stroke-linejoin="round"/><path d="M0,-6.4V1.2" stroke="${INK}" stroke-width="2.6" stroke-linecap="round"/><circle cy="5" r="1.5" fill="${INK}"/></svg>`;
}

/** A sea-battle marker for quest sea marks (crossed axes in a ring). */
export function seaMarkBadge(kind, size = 30) {
  const c = kind === 'main' ? GOLD : '#3f78b5';
  return `<svg viewBox="-15 -15 30 30" width="${size}" height="${size}" aria-hidden="true"><circle r="12.5" fill="${PARCH}" stroke="${c}" stroke-width="3"/><circle r="9.6" fill="none" stroke="${INK}" stroke-width=".6"/><path d="M-6,6L6,-6M6,6L-6,-6" stroke="${INK}" stroke-width="1.6" stroke-linecap="round"/><path d="M3.4,-8.4C6,-8 8.4,-5.6 8.6,-3.4L5.4,-4.2ZM-3.4,-8.4C-6,-8 -8.4,-5.6 -8.6,-3.4L-5.4,-4.2Z" fill="${WOOD}" stroke="${INK}" stroke-width=".7"/></svg>`;
}
